L32_1 = "\236\160\156\235\140\128\235\161\156 \235\144\156 \236\157\152\236\130\172\234\176\128 \236\151\134\236\150\180\236\132\156 \236\136\152\237\152\136\237\140\169\236\157\132 \235\182\153\236\157\180\234\179\160 \236\149\188\236\160\132 \236\157\145\234\184\137\235\178\149\236\156\188\235\161\156 \236\167\128\237\152\136 \236\160\149\235\143\132\235\167\140 \237\149\156 \234\177\176\236\149\188."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "\227\129\190\227\129\168\227\130\130\227\129\170\229\140\187\232\128\133\227\129\140\227\129\132\227\129\170\227\129\132\227\129\139\227\130\137\227\128\129\232\188\184\232\161\128\227\131\145\227\131\131\227\130\175\227\130\146\n\228\189\191\227\129\163\227\129\166\233\135\142\230\136\166\229\191\156\230\128\165\230\179\149\227\129\167\230\173\162\232\161\128\227\129\151\227\129\159\231\168\139\229\186\166\227\129\160\227\129\145\227\129\169\227\128\130"
L31_1.m_Talk_JPN = L32_1
L32_1 = "We gave you a blood transfusion and used a field tourniquet to stop the bleeding. Couldn\226\128\153t do much more without a proper doctor."
L31_1.m_Talk_ENG = L32_1
L32_1 = "\229\155\160\231\130\186\230\136\145\229\128\145\230\178\146\230\156\137\229\176\136\230\165\173\233\134\171\231\148\159\239\188\140\230\137\128\228\187\165\229\143\170\232\131\189\231\181\166\229\166\179\229\144\138\229\128\139\232\188\184\232\161\128\232\162\139\239\188\140\231\148\168\233\135\142\230\136\176\228\184\173\231\154\132\230\135\137\230\128\165\230\150\185\230\179\149\229\185\171\229\166\179\230\173\162\232\161\128\227\128\130"
L31_1.m_Talk_TWN = L32_1
L32_1 = "\224\185\128\224\184\163\224\184\178\224\185\131\224\184\171\224\185\137\224\185\128\224\184\165\224\184\183\224\184\173\224\184\148\224\184\129\224\184\177\224\184\154\224\185\128\224\184\152\224\184\173\224\185\129\224\184\165\224\184\176\224\185\131\224\184\138\224\185\137\224\184\170\224\184\178\224\184\162\224\184\163\224\184\177\224\184\148\224\184\160\224\184\178\224\184\132\224\184\170\224\184\153\224\184\178\224\184\161\224\184\171\224\185\137\224\184\178\224\184\161\224\185\128\224\184\165\224\184\183\224\184\173\224\184\148\224\184\130\224\184\173\224\184\135\224\185\128\224\184\152\224\184\173\224\185\132\224\184\167\224\185\137 \224\185\129\224\184\149\224\185\136\224\185\128\224\184\163\224\184\178\224\185\132\224\184\161\224\185\136\224\184\161\224\184\181\224\184\171\224\184\161\224\184\173 \224\184\129\224\185\135\224\185\128\224\184\165\224\184\162\224\184\151\224\184\179\224\184\173\224\184\176\224\185\132\224\184\163\224\184\161\224\184\178\224\184\129\224\185\132\224\184\161\224\185\136\224\184\132\224\185\136\224\184\173\224\184\162\224\185\132\224\184\148\224\185\137"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ch\195\186ng ta \196\145\195\163 c\225\186\167m m\195\161u v\195\160 truy\225\187\129n m\195\161u cho ng\198\176\198\161i. Kh\195\180ng th\225\187\131 l\195\160m \196\145\198\176\225\187\163c nhi\225\187\129u h\198\161n th\225\186\191 n\225\186\191u kh\195\180ng c\195\179 b\195\161c s\196\169."
L31_1.m_Talk_VTN = L32_1
L32_1 = "\232\191\153\233\135\140\230\178\161\230\156\137\228\184\147\228\184\154\229\140\187\231\148\159\239\188\140\230\137\128\228\187\165\229\143\170\231\187\153\228\189\160\231\148\168\232\190\147\232\161\128\232\162\139\232\190\147\232\161\128\239\188\140\231\148\168\233\135\142\230\136\152\228\184\173\231\154\132\229\186\148\230\128\165\230\150\185\230\179\149\231\187\153\228\189\160\230\173\162\232\161\128\227\128\130"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Wir haben dir eine Bluttransfusion gegeben und die Blutung vorerst mit einer Aderpresse gestoppt. Mehr war ohne richtigen Arzt nicht m\195\182glich."
L31_1.m_Talk_DEU = L32_1
L32_1 = "On t'a fait une transfusion sanguine et un garrot pour arr\195\170ter l'h\195\169morragie. Sans vrai m\195\169decin, c'est le mieux qu'on ait pu faire."
